def validate_record(record):
    def result(status, code, message):
        return {"status": status, "code": code, "message": message}

    edad = record.get("edad")
    if edad is None:
        edad_r = result("review", "MISSING", "Campo 'edad' ausente; envía un entero 0–120.")
    elif not isinstance(edad, int):
        edad_r = result("reject", "BAD_TYPE", f"Campo 'edad' recibió {edad!r}; se espera int.")
    elif edad < 0 or edad > 120:
        edad_r = result("reject", "OUT_OF_RANGE", f"Campo 'edad'={edad} fuera de 0–120.")
    elif edad < 18:
        edad_r = result("review", "NEEDS_REVIEW", f"Campo 'edad'={edad} requiere revisión.")
    else:
        edad_r = result("accept", "OK", "edad OK")

    region = record.get("region")
    allowed = {"Lima", "Arequipa", "Cusco", "Piura"}
    if region is None:
        region_r = result("review", "MISSING", "Campo 'region' ausente; completa la región.")
    elif not isinstance(region, str):
        region_r = result("reject", "BAD_TYPE", f"Campo 'region' recibió {region!r}; se espera str.")
    elif region not in allowed:
        region_r = result("review", "NOT_IN_ALLOWLIST", f"Campo 'region'={region!r} no está en el catálogo; revisa la captura.")
    else:
        region_r = result("accept", "OK", "region OK")

    monto = record.get("monto_ingreso")
    if monto is None:
        monto_r = result("review", "MISSING", "Campo 'monto_ingreso' ausente; completa el monto.")
    elif not isinstance(monto, (int, float)):
        monto_r = result("reject", "BAD_TYPE", f"Campo 'monto_ingreso' recibió {monto!r}; se espera número.")
    elif monto < 0:
        monto_r = result("reject", "OUT_OF_RANGE", f"Campo 'monto_ingreso'={monto} negativo; usa un valor ≥ 0.")
    elif monto > 50000:
        monto_r = result("review", "NEEDS_REVIEW", f"Campo 'monto_ingreso'={monto} supera 50000; revisa la captura.")
    else:
        monto_r = result("accept", "OK", "monto OK")

    fields = {"edad": edad_r, "region": region_r, "monto_ingreso": monto_r}
    statuses = [r["status"] for r in fields.values()]
    if "reject" in statuses:
        status = "reject"
    elif "review" in statuses:
        status = "review"
    else:
        status = "accept"
    return {"status": status, "fields": fields}


def process_batch(records):
    results = []
    n_accept = n_reject = n_review = 0
    for record in records:
        checked = validate_record(record)
        status = checked["status"]
        results.append({"raw": record.copy(), "status": status, "fields": checked["fields"]})
        if status == "accept":
            n_accept += 1
        elif status == "reject":
            n_reject += 1
        else:
            n_review += 1
    n_total = len(results)
    tasa_reject = n_reject / n_total if n_total else None
    return {"n_total": n_total, "n_accept": n_accept, "n_reject": n_reject, "n_review": n_review, "tasa_reject": tasa_reject, "results": results}


def format_report(summary):
    return f"n_total {summary['n_total']}\naccept {summary['n_accept']}\nreject {summary['n_reject']}\nreview {summary['n_review']}\ntasa_reject {summary['tasa_reject']}"
